import React from "react";

// Import portfolio images
import stock from "../img/image1.jpg";
import stock1 from "../img/image2.jpg";
import stock2 from "../img/image3.jpg";
import stock3 from "../img/image4.jpg";
import stock4 from "../img/image5.jpg";
import stock5 from "../img/image6.jpg";

class Portfolio extends React.Component {
  render() {
    // Data-driven projects to avoid repetition and warnings
    const projects = [
      {
        id: "vmarine",
        title: "Emotion Recognition System",
        category: "React • Node.js • Python • ML",
        mainImage: stock,
        gallery: [stock1, stock2, stock3, stock4, stock5],
      },
      {
        id: "aguadeluz",
        title: "Flip Emoji Match Game",
        category: "JavaScript • CSS3 • React",
        mainImage: stock2,
        gallery: [stock1, stock3, stock4, stock5],
      },
      {
        id: "todo",
        title: "Vehicle Management Dashboard",
        category: "React • Bootstrap • REST APIs",
        mainImage: stock3,
        gallery: [stock1, stock2, stock4, stock5],
      },
      {
        id: "medlingos",
        title: "Mobility Solutions Portal",
        category: "Node.js • Express • PostgreSQL",
        mainImage: stock4,
        gallery: [stock1, stock2, stock3, stock5],
      },
      {
        id: "smth",
        title: "UI/UX Portfolio Website",
        category: "HTML5 • CSS3 • Animations",
        mainImage: stock5,
        gallery: [stock2, stock3, stock4],
      },
      {
        id: "mf",
        title: "Cloud Deployment Pipeline",
        category: "AWS • CI/CD • Scalable Architecture",
        mainImage: stock1,
        gallery: [stock2, stock3, stock4, stock5],
      },
    ];

    return (
      <section id="work" className="portfolio-mf sect-pt4 route">
        <div className="container">
          {/* Section Title */}
          <div className="row">
            <div className="col-sm-12">
              <div className="title-box text-center">
                <h3 className="title-a gradient-text">Portfolio</h3>
                <p className="subtitle-a glow-text">
                  A showcase of my projects — clean UI, scalable backends, and smooth user experiences.
                </p>
                <div className="line-mf"></div>
              </div>
            </div>
          </div>

          {/* Portfolio Grid */}
          <div className="row no-gutters">
            {projects.map((project) => (
              <div className="col-12 col-sm-6 col-lg-4" key={project.id}>
                <div className="work-box">
                  {/* Anchor only on image to reduce layout shifts */}
                  <a
                    href={project.mainImage}
                    data-lightbox={`gallery-${project.id}`}
                    rel="noopener"
                    aria-label={`${project.title} gallery`}
                  >
                    <div className="work-img">
                      <img
                        src={project.mainImage}
                        alt={project.title}
                        className="img-fluid"
                        loading="lazy"
                        decoding="async"
                        style={{
                          width: "100%",
                          height: "auto",
                          display: "block",
                          objectFit: "cover",
                        }}
                      />
                    </div>
                  </a>

                  <div className="work-content">
                    <div className="row">
                      <div className="col-sm-8">
                        <h2 className="w-title">{project.title}</h2>
                        <div className="w-more">
                          <span className="w-ctegory">{project.category}</span>
                        </div>
                      </div>
                      <div className="col-sm-4">
                        <div className="w-like" aria-hidden="true">
                          <span className="ion-ios-plus-outline"></span>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Hidden gallery images with content to avoid a11y warnings */}
                  {project.gallery.map((img, idx) => (
                    <a
                      key={`${project.id}-extra-${idx}`}
                      href={img}
                      data-lightbox={`gallery-${project.id}`}
                      style={{ display: "none" }}
                      aria-label={`${project.title} extra image ${idx + 1}`}
                    >
                      {project.title} image {idx + 1}
                    </a>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Inline defensive style to prevent horizontal scroll if any child overflows */}
        <style>
          {`
            #work {
              overflow-x: hidden;
            }
            .row.no-gutters {
              margin-right: 0;
              margin-left: 0;
            }
            .row.no-gutters > [class^='col-'], 
            .row.no-gutters > [class*=' col-'] {
              padding-right: 0;
              padding-left: 0;
            }
            .work-box {
              will-change: transform;
              transition: transform 200ms ease, box-shadow 200ms ease;
            }
            .work-box:hover {
              transform: translateZ(0) scale(1.02);
              box-shadow: 0 10px 20px rgba(0,0,0,0.12);
            }
            .work-content {
              padding: 1.25rem 1rem 1rem 1rem;
            }
            .w-title {
              margin-bottom: .25rem;
            }
            /* Ensure images don't cause layout shift */
            .work-img img {
              max-width: 100%;
              height: auto;
              display: block;
            }
          `}
        </style>
      </section>
    );
  }
}

export default Portfolio;
